import os
from typing import Any, Dict, Optional

import requests


AUTH0_DOMAIN = os.getenv("AUTH0_DOMAIN")
AUTH0_CLIENT_ID = os.getenv("AUTH0_CLIENT_ID")
AUTH0_CLIENT_SECRET = os.getenv("AUTH0_CLIENT_SECRET")
AUTH0_AUDIENCE = os.getenv("AUTH0_AUDIENCE")
AUTH0_TOKEN_URL = f"https://{AUTH0_DOMAIN}/oauth/token" if AUTH0_DOMAIN else None


class Auth0TokenRefreshError(Exception):
    pass


def refresh_expired_session(refresh_token: str, scope: Optional[str] = None) -> Dict[str, Any]:
    if not AUTH0_DOMAIN or not AUTH0_CLIENT_ID or not AUTH0_CLIENT_SECRET:
        raise Auth0TokenRefreshError(
            "Missing required Auth0 environment variables: AUTH0_DOMAIN, AUTH0_CLIENT_ID, AUTH0_CLIENT_SECRET"
        )
    if not refresh_token:
        raise Auth0TokenRefreshError("refresh_token is required")
    if not AUTH0_TOKEN_URL:
        raise Auth0TokenRefreshError("Invalid Auth0 domain")

    payload: Dict[str, Any] = {
        "grant_type": "refresh_token",
        "client_id": AUTH0_CLIENT_ID,
        "client_secret": AUTH0_CLIENT_SECRET,
        "refresh_token": refresh_token,
    }
    if AUTH0_AUDIENCE:
        payload["audience"] = AUTH0_AUDIENCE
    if scope:
        payload["scope"] = scope

    response = requests.post(
        AUTH0_TOKEN_URL,
        json=payload,
        headers={"Content-Type": "application/json"},
        timeout=30,
    )

    if response.status_code != 200:
        try:
            error_detail = response.json()
        except ValueError:
            error_detail = response.text
        raise Auth0TokenRefreshError(f"Auth0 token refresh failed: {response.status_code} {error_detail}")

    data = response.json()
    normalized = {
        "access_token": data.get("access_token"),
        "id_token": data.get("id_token"),
        "refresh_token": data.get("refresh_token", refresh_token),
        "token_type": data.get("token_type"),
        "expires_in": data.get("expires_in"),
        "scope": data.get("scope"),
    }
    return normalized


def refresh_access_token(refresh_token: str) -> str:
    return refresh_expired_session(refresh_token)["access_token"]
